import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import DataTable from 'datatables.net-react';
import DT from 'datatables.net-dt';
import 'datatables.net-dt/css/dataTables.dataTables.css';

DataTable.use(DT);

const BaselineDetailsPage = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { baselineData, selectedMonth, selectedYear } = location.state || {};

  if (!baselineData || !baselineData.details) {
    return (
      <div className="details-page">
        <h2>Baseline Details</h2>
        <p>No Baseline data available. Please go back to the dashboard.</p>
        <button onClick={() => navigate('/')}>Go to Dashboard</button>
      </div>
    );
  }

  const formatCurrency = (value) =>
    new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(value ?? 0);

  // Calculate quarterly revenue
  const q1Revenue = baselineData.details
    .filter((row) => [1, 2, 3].includes(new Date(row.startDate).getMonth() + 1))
    .reduce((sum, row) => sum + (row.monthRevenue ?? 0), 0);

  const q2Revenue = baselineData.details
    .filter((row) => [4, 5, 6].includes(new Date(row.startDate).getMonth() + 1))
    .reduce((sum, row) => sum + (row.monthRevenue ?? 0), 0);

  const q3Revenue = baselineData.details
    .filter((row) => [7, 8, 9].includes(new Date(row.startDate).getMonth() + 1))
    .reduce((sum, row) => sum + (row.monthRevenue ?? 0), 0);

  const columns = [
    { title: 'Associate ID', data: 'associateId' },
    { title: 'Name', data: 'name' },
    { title: 'Service Line', data: 'serviceLine' },
    { title: 'Project ID', data: 'projectId' },
    { title: 'Project Name', data: 'projectName' },
    { title: 'Start Date', data: 'startDate' },
    { title: 'End Date', data: 'endDate' },
    { title: 'Current Start', data: 'currentStartDate' },
    { title: 'Current End', data: 'currentEndDate' },
    { title: 'Billability', data: 'billabilityType' },
    { title: 'City', data: 'city' },
    { title: 'State', data: 'state' },
    { title: 'Rate', data: 'rate' },
    { title: 'Hours', data: 'hours' },
    { title: 'Month Hours', data: 'monthHours' },
    { title: 'Month Revenue', data: 'monthRevenue' },
    { title: 'Prev Revenue', data: 'prevMonthRevenue' },
    { title: 'Variance', data: 'variance' },
    { title: 'Reason', data: 'varianceReason' },
  ];

  return (
    <div className="details-page">
      <button onClick={() => navigate('/')}>Back to Dashboard</button>
      <h2>Baseline Details</h2>

      <div className="quarter-summary">
        <h3>Quarterly Revenue Summary</h3>
        <ul>
          <li><strong>Q1 (Jan–Mar):</strong> {formatCurrency(q1Revenue)}</li>
          <li><strong>Q2 (Apr–Jun):</strong> {formatCurrency(q2Revenue)}</li>
          <li><strong>Q3 (Jul–Sep):</strong> {formatCurrency(q3Revenue)}</li>
        </ul>
      </div>

      <DataTable
        columns={columns}
        data={baselineData.details}
        options={{ paging: true, searching: true, info: true }}
      />
    </div>
  );
};

export default BaselineDetailsPage;
